# Write CSV file: {file_path}
import csv
data = {data}
header = {header}
with open('{file_path}', 'w', newline='', encoding='utf-8') as f:
    writer = csv.writer(f)
    if header:
        writer.writerow(header)
    for row in data:
        if isinstance(row, (list, tuple)):
            writer.writerow(row)
        else:
            writer.writerow([row])
